  // Opções de setor pro editor: setores ativos (sem 'Todos') + o atual se não estiver na lista.
  const setoresParaEdicao = (atual?: string | null): string[] => {
    const base = setoresGestao.map((s) => s.nome).filter((n) => n !== 'Todos');
    if (atual && !base.includes(atual)) return [atual, ...base];
    return base;
  };

  const saveProduct = async (produto: Partial<ProdutoComCategoria>) => {
    if (!produto.nome) {
      toast({ title: 'Nome do produto é obrigatório', variant: 'destructive' });
      return;
    }

    if (!hasData) {
      toast({ title: 'Selecione uma loja primeiro', variant: 'destructive' });
      return;
    }

    const startTime = performance.now();
    const operacao = produto.id ? 'update' : 'insert';

    // Preparar dados para o catálogo mestre (sem loja_id)
    const productMasterData = {
      nome: produto.nome,
      nome_normalizado: produto.nome.trim().toLowerCase(),
      descricao: produto.descricao,
      codigo_interno: produto.codigo_interno,
      preco_custo: produto.preco_custo,
      unidade_medida: produto.unidade_medida || 'unidade',
      ativo: produto.ativo ?? true,
      setor: normalizeSetorForDb(produto.setor || setorSelecionado),
      foto_url: produto.foto_url,
      dias_validade: produto.dias_validade,
    };

    let produtoId = produto.id;

    if (produto.id) {
      // Atualizar produto existente no catálogo mestre
      const { error } = await supabase
        .from('produtos_master') // Tabela Mestre
        .update(productMasterData)
        .eq('id', produto.id);

      if (error) {
        handleError(error, { domain: 'produtos', operation: 'updateProductMaster', showToast: false });
        toast({ title: 'Erro ao atualizar produto', variant: 'destructive' });
        wideError('produto.erro', 'Erro ao atualizar produto', {
          attributes: {
            'error.message': error.message,
            'produto.operacao': operacao,
            'duration_ms': Math.round(performance.now() - startTime),
          },
        });
        recordError('produto_salvar', operacao);
        return;
      }
    } else {
      // Criar novo produto no catálogo mestre
      const { data, error } = await supabase
        .from('produtos_master')
        .insert(productMasterData)
        .select('id')
        .single();

      if (error) {
        handleError(error, { domain: 'produtos', operation: 'createProductMaster', showToast: false });
        toast({ title: 'Erro ao criar produto', variant: 'destructive' });
        wideError('produto.erro', 'Erro ao criar produto', {
          attributes: {
            'error.message': error.message,
            'produto.operacao': operacao,
            'duration_ms': Math.round(performance.now() - startTime),
          },
        });
        recordError('produto_salvar', operacao);
        return;
      }

      produtoId = data.id;

      // Log de criação
      try {
        const resolveUsuarioId = async (): Promise<number | null> => {
          const { data: rpcId } = await supabase.rpc(
            'get_usuario_id_from_auth',
            { user_uuid: user?.id },
          );
          return (rpcId as number) || null;
        };
        const usuarioIdData = await resolveUsuarioId();

        await supabase.from('movimentacoes').insert({
          produto_master_id: produtoId, // Novo campo
          tipo_movimentacao: 'cadastro',
          quantidade: 0,
          usuario_id: usuarioIdData,
          motivo: 'novo_produto',
          observacoes: `novo produto [${productMasterData.nome}] criado.`,
          data_movimentacao: new Date().toISOString(),
          loja_id: storeId,
        });
      } catch {
        /* intentional */
      }
    }

    // Salvar dados de estoque (vínculo loja -> mestre)
    if (
      produtoId &&
      (produto.quantidade_atual !== undefined ||
        produto.quantidade_minima !== undefined ||
        produto.quantidade_maxima !== undefined)
    ) {
      const estoqueData = {
        produto_master_id: produtoId, // USAR CAMPO NOVO
        loja_id: storeId,
        quantidade_atual: produto.quantidade_atual || 0,
        // ?? para não sobrescrever mínimo 0 legítimo (calculado por demanda)
        quantidade_minima: produto.quantidade_minima ?? 0,
        quantidade_maxima: produto.quantidade_maxima || 100,
        updated_at: new Date().toISOString(),
      };

      const { error: estoqueError } = await supabase
        .from('estoque')
        .upsert(estoqueData, { onConflict: 'produto_master_id,loja_id' }); // Constraint correta

      if (estoqueError) {
        handleError(estoqueError, { domain: 'produtos', operation: 'saveEstoque', showToast: false });
        toast({
          title: 'Produto salvo, mas erro ao atualizar estoque',
          variant: 'destructive',
        });
      }
    }

    const durationMs = Math.round(performance.now() - startTime);
    wideInfo('produto.salvo', 'Produto salvo com sucesso', {
      attributes: {
        'produto.nome': produto.nome || '',
        'produto.operacao': operacao,
        'duration_ms': durationMs,
      },
    });
    recordOperation('produto.salvar');
    recordOperationDuration('produto.salvar', durationMs);

    toast({ title: 'Produto salvo com sucesso!' });
    fetchProdutos();
    setEditingProduct(null);
    setShowNewProduct(false);
    setNewProduct({
      nome: '',
      descricao: '',
      unidade_medida: 'unidade',
      ativo: true,
      setor: setorSelecionado,
    });
  };

  const fetchProductHistory = async (productId: number) => {
    setLoadingHistory(true);
    setShowHistoryModal(productId);
    try {
      const { data, error } = await supabase
        .from('movimentacoes')
        .select('*')
        .eq('produto_master_id', productId)
        .order('data_movimentacao', { ascending: false })
        .limit(50);

      if (error) throw error;
      setProductHistory(data || []);
    } catch (e) {
      handleError(e, { domain: 'produtos', operation: 'fetchHistory', showToast: false });
      toast({ title: 'Erro ao carregar histórico', variant: 'destructive' });
    } finally {
      setLoadingHistory(false);
    }
  };

  const deleteProduct = async (id: number) => {
    if (!hasData) {
      toast({ title: 'Selecione uma loja primeiro', variant: 'destructive' });
      return;
    }

    if (!isAdmin()) {
      toast({
        title: 'Acesso Negado',
        description:
          "Apenas administradores podem arquivar produtos do Catálogo Global. Utilize o botão de 'Ocultar' (Olho) para removê-lo da sua loja.",
        variant: 'destructive',
      });
      return;
    }

    const productName = produtos.find((p) => p.id === id)?.nome || '';

    if (
      confirm(
        `ADMIN: Tem certeza que deseja ARQUIVAR o produto "${productName}"? Ele ficará indisponível para TODAS AS LOJAS.`,
      )
    ) {
      try {
        const resolveUsuarioId = async (): Promise<number | null> => {
          const { data: rpcId } = await supabase.rpc(
            'get_usuario_id_from_auth',
            { user_uuid: user?.id },
          );
          return (rpcId as number) || null;
        };
        const usuarioIdData = await resolveUsuarioId();

        // 1. Soft Delete (Archive)
        const { error } = await supabase
          .from('produtos_master')
          .update({ ativo: false })
          .eq('id', id);

        if (error) throw error;

        // 2. Log Action
        await supabase.from('movimentacoes').insert({
          produto_master_id: id,
          tipo_movimentacao: 'exclusao', // Keep logic type
          quantidade: 0,
          usuario_id: usuarioIdData,
          motivo: 'produto_arquivado',
          observacoes: `produto [${productName}] arquivado (soft-delete) do catálogo mestre.`,
          data_movimentacao: new Date().toISOString(),
          loja_id: storeId,
        });

        toast({
          title: 'Produto arquivado com sucesso!',
          description: "Você pode vê-lo no filtro 'Arquivados'.",
        });
        fetchProdutos();
      } catch (error) {
        handleError(error, { domain: 'produtos', operation: 'archiveProduct', showToast: false });
        toast({ title: 'Erro ao arquivar produto', variant: 'destructive' });
      }
    }
  };

  const restoreProduct = async (id: number) => {
    if (!isAdmin()) return;
    try {
      const { error } = await supabase
        .from('produtos_master')
        .update({ ativo: true })
        .eq('id', id);

      if (error) throw error;
      toast({ title: 'Produto restaurado com sucesso!' });
      fetchProdutos();
    } catch (e) {
      toast({ title: 'Erro ao restaurar', variant: 'destructive' });
    }
  };

  const uploadImage = async (file: File, productId?: number) => {
    try {
      setUploadingImage(productId || -1);

      const fileExt = file.name.split('.').pop();
      const fileName = `${Date.now()}.${fileExt}`;
      const filePath = `produtos/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('produto-fotos')
        .upload(filePath, file);

      if (uploadError) {
        throw uploadError;
      }

      const {
        data: { publicUrl },
      } = supabase.storage.from('produto-fotos').getPublicUrl(filePath);

      return publicUrl;
    } catch (error) {
      handleError(error, { domain: 'produtos', operation: 'uploadImage', showToast: false });
      toast({
        title: 'Erro ao fazer upload da imagem',
        variant: 'destructive',
      });
      return null;
    } finally {
      setUploadingImage(null);
    }
  };

  const handleImageUpload = async (
    event: React.ChangeEvent<HTMLInputElement>,
    productId?: number,
  ) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const imageUrl = await uploadImage(file, productId);
    if (imageUrl) {
      if (productId) {
        // Atualizar produto existente
        const updatedProdutos = produtos.map((p) =>
          p.id === productId ? { ...p, foto_url: imageUrl } : p,
        );
        setProdutos(updatedProdutos);

        // Salvar no banco
        await supabase
          .from('produtos_master') // Updated from 'produtos' to 'produtos_master'
          .update({ foto_url: imageUrl })
          .eq('id', productId);
      } else {
        // Novo produto
        setNewProduct({ ...newProduct, foto_url: imageUrl });
      }
      toast({ title: 'Imagem carregada com sucesso!' });
    }
  };

  // Agrupar produtos filtrados por setor (categoria foi abandonada)
  const produtosPorSetor = (() => {
    const map = new Map<string, ProdutoComCategoria[]>();
    for (const produto of produtosFiltrados) {
      const key = (produto.setor || 'Sem Setor').trim() || 'Sem Setor';
      if (!map.has(key)) map.set(key, []);
      map.get(key)!.push(produto);
    }
    return Array.from(map.entries()).sort((a, b) => a[0].localeCompare(b[0], 'pt-BR'));
  })();


  const generateAndPrintHTML = (
    title: string,
    items: ItemRelatorio[],
    groupedBySector: boolean,
  ) => {
    const dateStr = new Date().toLocaleDateString('pt-BR', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric',
    });
    const timeStr = new Date().toLocaleTimeString('pt-BR', {
      hour: '2-digit',
      minute: '2-digit',
    });

    // Agrupar itens
    const groups: Record<string, Record<string, ItemRelatorio[]>> = {}; // Setor -> Categoria -> Itens

    items.forEach((item) => {
      const gSetor = item.setor || 'Outros';
      const gCat = item.categoria || 'Sem Categoria';

      if (!groups[gSetor]) groups[gSetor] = {};
      if (!groups[gSetor][gCat]) groups[gSetor][gCat] = [];

      groups[gSetor][gCat].push(item);
    });

    // Ordenar setores e categorias
    const sortedSetores = Object.keys(groups).sort();

    let contentHTML = '';

    sortedSetores.forEach((setorName) => {
      const categoriasDoSetor = groups[setorName];
      const sortedCategorias = Object.keys(categoriasDoSetor).sort();

      // Cabeçalho do Setor (se estiver agrupando por setor, ou se for apenas um setor mas quisermos mostrar)
      contentHTML += `<div class="sector-header">${setorName.toUpperCase()}</div>`;

      sortedCategorias.forEach((catName) => {
        contentHTML += `
          <div class="category-header">${catName.toUpperCase()}</div>
          <table class="items-table">
            <thead>
              <tr>
                <th style="width: 10%">COD</th>
                <th style="width: 40%">PRODUTO</th>
                <th style="width: 10%">UN</th>
                <th style="width: 15%">QTD. SISTEMA</th>
                <th style="width: 25%">CONTAGEM FÍSICA</th>
              </tr>
            </thead>
            <tbody>
        `;

        const catItems = categoriasDoSetor[catName].sort((a, b) =>
          a.nome.localeCompare(b.nome),
        );

        catItems.forEach((item) => {
          contentHTML += `
            <tr>
              <td class="center" style="font-size: 8px; color: #666;">${item.codigo_interno || '-'}</td>
              <td class="product-name">${item.nome}</td>
              <td class="center">${item.unidade}</td>
              <td class="center quantity-system">${item.quantidade_sistema !== undefined && item.quantidade_sistema !== null ? item.quantidade_sistema : 0}</td>
              <td class="write-area"></td>
            </tr>
          `;
        });

        contentHTML += `
            </tbody>
          </table>
        `;
      });

